// FlushPostIngestCache evicts all cached post_ingest schedule lookup entries
// so turning off/on Realtime Sync takes effect immediately across all buffers.
func (bb *BatchBuffer) FlushPostIngestCache() {
	bb.piCache.Range(func(k, _ any) bool {
		bb.piCache.Delete(k)
		return true
	})
}

// InvalidateConnectionAdapter removes per-connection SchemaAdapter instances
// bound to a retired connection pool so closed *gorm.DB handles are never reused.
func (bb *BatchBuffer) InvalidateConnectionAdapter(connKey string) {
	connKey = strings.TrimSpace(connKey)
	if connKey == "" {
		return
	}
	for _, prefix := range []string{"master:", "shadow:"} {
		if v, ok := bb.adapters.LoadAndDelete(prefix + connKey); ok {
			if adapter, ok := v.(*serviceshadow.SchemaAdapter); ok && adapter != nil {
				adapter.FlushAll()
			}
		}
	}
}

// FlushSchemaCache evicts all cached table schemas from every per-connection
// SchemaAdapter held in bb.adapters, plus the default bb.schemaAdapter.
// Call this whenever a schema.config.reload event fires so newly-added columns
// are picked up on the next upsert without a process restart.
func (bb *BatchBuffer) FlushSchemaCache() {
	bb.adapters.Range(func(_, v any) bool {
		v.(*serviceshadow.SchemaAdapter).FlushAll()
		return true
	})
	bb.schemaAdapter.FlushAll()
	bb.FlushPostIngestCache()
}

